-- Seed the starting price only when no price history exists.
INSERT INTO ticket_price_history (ticket_id, price, changed_at)
SELECT t.id, t.price, COALESCE(t.sales_start_at, @ticket_seed_now)
FROM tickets t
LEFT JOIN ticket_price_history h ON h.ticket_id = t.id
WHERE t.id BETWEEN 1 AND 163
  AND h.id IS NULL;

COMMIT;
